Does it render?

library(ggplot2)

dk() |&gt;
  atlas_region_keep("temporal") |&gt;
  brain_test_plot(
    position = position_brain(hemi ~ view)
  )








brain_test_plot() draws every region in its palette colour, so a region that has lost its geometry shows up as a hole. plot(atlas) is the quick version, and atlas_plot_palette(atlas) shows the colours on their own.

A glass brain around a subcortical atlas

ggseg3d(atlas = aseg()) |&gt;
  add_glassbrain("left", opacity = 0.2) |&gt;
  pan_camera("left lateral")

add_glassbrain(
  p, hemisphere = c("left", "right"),
  surface = "inflated", colour = "#CCCCCC",
  opacity = 0.3, brain_meshes = NULL
)

Saving a still image

ggseg3d(atlas = dk()) |&gt;
  pan_camera("left lateral") |&gt;
  snapshot_brain(
    "brain.png",
    width = 600, height = 500, zoom = 2
  )

snapshot_brain() drives a headless browser, so it needs webshot2 and Chrome. For a plot destined for print, ggsegray() renders the same scene through rgl instead:

ggsegray(atlas = dk(), colour_by = "colour") |&gt;
  pan_camera("right lateral")

Widget bindings

ui &lt;- fluidPage(
  ggseg3dOutput(
    "brain",
    width = "100%",
    height = "600px"
  )
)

server &lt;- function(input, output, session) {
  output$brain &lt;- renderGgseg3d({
    ggseg3d(
      .data = scores(),
      atlas = dk(),
      colour_by = "score"
    )
  })
}
